  const w2y = Math.cos(sy*0.028+t*0.55)*6 + Math.sin(sx*0.022-t*0.5)*5;
  const fx = sx+w2x, fy = sy+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9],
    [80+Math.sin(t*0.65+3)*70, 40+Math.cos(t*0.45+2)*55, 0.11, 2.1],
    [400+Math.cos(t*0.55+1)*85, 200+Math.sin(t*0.75+4)*65, 0.085, 1.8],
    [200+Math.sin(t*0.42+6)*95, 220+Math.cos(t*0.62+3)*75, 0.095, 2.4]
  ];
  let aS=0, iS=0, aS2=0, iS2=0;
  for(const[sX,sY,f,sp]of src){
    const d=Math.sqrt((fx-sX)**2+(fy-sY)**2);
    aS+=Math.sin(d*f-t*sp);
    iS+=Math.sin(d*f*0.7+t*sp*0.6+1.5);
    aS2+=Math.sin(d*f*1.8-t*sp*1.3+0.7);
    iS2+=Math.sin(d*f*1.2+t*sp*0.9+2.8);
  }
  const n=9;
  const act=aS/n, inh=iS/n, act2=aS2/n, inh2=iS2/n;
  const bg=(Math.sin(fx*0.04+fy*0.025+t*0.8)+Math.sin(fx*0.03-fy*0.04+t*1.1))/2+Math.sin((fx+fy)*0.12+t*2.5)*0.2+Math.sin((fx-fy)*0.1-t*2)*0.2;
  const dist=Math.sqrt((fx-cx)**2+(fy-cy)**2), ang=Math.atan2(fy-cy,fx-cx);
  const spiral=(Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2))*0.4;
  const spiral2=(Math.sin(dist*0.08+ang*2-t*2.1)+Math.cos(dist*0.06-ang*5+t*1.7))*0.25;
