  const reaction=Math.tanh((act-inh*0.7+bg*0.3+spiral)*2.2);
  const reaction2=Math.tanh((act2-inh2*0.6+spiral2+micro)*1.8);
  const coupled=Math.tanh((reaction*0.65+reaction2*0.35+Math.sin(reaction*reaction2*Math.PI*2)*0.15)*2.0);
  const cell=Math.tanh((Math.sin(fx*0.15)*Math.sin(fy*0.15)+Math.sin((fx+fy)*0.1+t)*0.5)*1.5)*0.3;
  const breath=0.92+Math.sin(t*0.4)*0.08;
  const blend=coupled*0.7+cell*0.3, v=blend*0.5+0.5;
  const lum=0.78+Math.sin(coupled*Math.PI)*0.22;
  const edge=Math.abs(coupled)>0.72?1.18:Math.abs(coupled)>0.5?1.05:0.95;
  const glow=Math.max(0,coupled*0.3)*0.15;
  const pal=[[12,8,48],[18,45,98],[22,95,128],[28,148,138],[145,178,95],[208,188,58],[218,138,72],[195,72,68],[128,32,72],[62,18,58],[12,8,48]];
  const idx=v*(pal.length-1), i=Math.min(idx|0,pal.length-2), f=idx-i;
