  const g0=pal[i][1]+(pal[i+1][1]-pal[i][1])*f;
  const b0=pal[i][2]+(pal[i+1][2]-pal[i][2])*f;
  return[
    Math.min(255,Math.max(0,(r0*lum*edge*breath+glow*180)|0)),
    Math.min(255,Math.max(0,(g0*lum*edge*breath+glow*140)|0)),
    Math.min(255,Math.max(0,(b0*lum*edge*breath+glow*200)|0))
  ];
}
